CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, name TEXT, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(ip TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY, name TEXT NOT NULL, short_name TEXT, kind TEXT NOT NULL DEFAULT 'school', contact TEXT, phone TEXT, email TEXT, address TEXT, payment_terms TEXT, deposit_pct INTEGER, notes TEXT, created TEXT);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, name TEXT NOT NULL, invoice_no TEXT, placed TEXT, due TEXT, stage TEXT NOT NULL DEFAULT 'Draft', discount INTEGER NOT NULL DEFAULT 0, note TEXT);
CREATE TABLE IF NOT EXISTS order_lines(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, line_no INTEGER NOT NULL, item TEXT NOT NULL, detail TEXT, qty INTEGER NOT NULL, unit_price INTEGER NOT NULL, sizes TEXT, design TEXT);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, date TEXT, method TEXT, amount INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS order_changes(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, date TEXT, by TEXT, change TEXT, amount INTEGER, reason TEXT);
CREATE TABLE IF NOT EXISTS stage_log(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, at TEXT, by TEXT, from_stage TEXT, to_stage TEXT);
CREATE TABLE IF NOT EXISTS stock_items(id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT, unit TEXT, on_hand REAL NOT NULL DEFAULT 0, reserved REAL NOT NULL DEFAULT 0, supplier TEXT, cost INTEGER, warn_below REAL);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT, item_id TEXT NOT NULL, date TEXT, kind TEXT, reference TEXT, change REAL, on_hand_after REAL);
CREATE TABLE IF NOT EXISTS prices(item TEXT PRIMARY KEY, standard INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS price_overrides(customer_id TEXT, item TEXT, price INTEGER, reason TEXT, PRIMARY KEY(customer_id,item));
CREATE TABLE IF NOT EXISTS garments(name TEXT PRIMARY KEY, json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS houses(id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id TEXT, house TEXT, colour TEXT, jersey TEXT, badge TEXT);
CREATE TABLE IF NOT EXISTS crests(id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id TEXT, name TEXT, used_on TEXT, badge TEXT);
